// This code was written by an AI (Claude Fable 5.2). Read it before you trust it.
//
// Generated by scripts/build.mjs from extension/src/. Do not edit this file:
// change the sources and run "npm run build".

// What counts as a spoiler.
//
// Every entry is a piece of a regular expression. It is matched against
// normalised text (see matcher.js): lower-case, accents removed, and
// _ - + . / # : | turned into spaces. So write entries in lower-case and use
// \\s* or \\s+ where people might or might not type a space.
//
// Forking this for another game? This file is the only one you have to change.
(() => {
  'use strict';
  const SS = (globalThis.SpoilerShield ??= {});

  SS.keywords = {
    // Shown on the bar that replaces a hidden post.
    label: 'GTA 6',

    // One hit is enough to hide.
    strong: [
      'gta', // also catches gta6, gta 6, #gta6: anything where "gta" is not followed by a letter
      'gta\\s*(?:vi|six)',
      'g\\s+t\\s+a\\s+(?:6|vi)', // "G.T.A. 6"
      'grand\\s*theft\\s*auto',
      'vice\\s*city',
      'leonida',
      'rockstar\\s*games',
      'rockstar\\s*north',
      // Names from the official trailers.
      'jason\\s+duval',
      'lucia\\s+caminos',
      'cal\\s+hampton',
      'boobie\\s+ike',
      'dre\\s*quan',
      'real\\s+dimez',
      'raul\\s+bautista',
      'brian\\s+heder',
      'port\\s+gellhorn',
      'grassrivers',
      'mount\\s+kalaga',
    ],

    // Ordinary words. A block of text is hidden only when it contains at least
    // `weakThreshold` different ones, so "Jason went to the shop" stays visible
    // and "Jason and Lucia rob a store" does not.
    weak: ['rockstar', 'jason', 'lucia', 'duval', 'caminos', 'take\\s*two', 'ambrosia', 'trailer\\s*[23]'],
    weakThreshold: 2,
  };
})();

// Site adapters.
//
// An adapter is a hostname pattern plus a CSS selector for that site's
// "cards": one post, one video tile, one comment. When a card's text is a
// spoiler the whole card collapses into a bar, thumbnail included.
//
// Sites without an adapter still work: matching text is blurred (see
// shield.js). An adapter only makes the result tidier.
//
// Sites rename their elements a few times a year. If something slips through,
// open DevTools, find the element that wraps the whole post and add its
// selector here, with a fixture in test/browser/fixtures/.
(() => {
  'use strict';
  const SS = (globalThis.SpoilerShield ??= {});

  const SITES = [
    {
      name: 'reddit',
      host: /(^|\.)reddit\.com$/,
      cards: [
        'shreddit-post',
        'shreddit-comment',
        'shreddit-ad-post',
        'reddit-pdp-right-rail-post',
        'community-highlight-card',
        '[data-testid="search-post-unit"]',
        '[data-testid="search-community"]',
        '.thing', // old.reddit.com posts and comments
        '.search-result',
      ],
    },
    {
      name: 'youtube',
      host: /(^|\.)youtube\.com$/,
      cards: [
        'ytd-rich-item-renderer',
        'ytd-video-renderer',
        'ytd-compact-video-renderer',
        'ytd-grid-video-renderer',
        'ytd-playlist-renderer',
        'ytd-radio-renderer',
        'ytd-channel-renderer',
        'ytd-movie-renderer',
        'ytd-reel-item-renderer',
        'ytd-reel-video-renderer',
        'ytd-playlist-video-renderer',
        'ytd-playlist-panel-video-renderer',
        'ytd-comment-thread-renderer',
        'ytd-notification-renderer',
        'ytd-post-renderer',
        'ytd-backstage-post-thread-renderer',
        'yt-lockup-view-model',
        'ytm-shorts-lockup-view-model',
        'ytm-shorts-lockup-view-model-v2',
        '.ytp-videowall-still', // end-of-video suggestions
        '.ytp-ce-element',
        // m.youtube.com
        'ytm-rich-item-renderer',
        'ytm-video-with-context-renderer',
        'ytm-compact-video-renderer',
        'ytm-comment-thread-renderer',
        'ytm-reel-item-renderer',
      ],
    },
    {
      name: 'instagram',
      host: /(^|\.)instagram\.com$/,
      cards: ['article', 'main a[href*="/p/"]:not(article a)', 'main a[href*="/reel/"]:not(article a)'],
    },
    {
      name: 'x',
      host: /(^|\.)(x|twitter)\.com$/,
      cards: ['article[data-testid="tweet"]', '[data-testid="trend"]', '[data-testid="UserCell"]'],
    },
  ];

  SS.sites = {
    list: SITES,
    /** Returns { name, selector } for a hostname, or null when there is no adapter. */
    forHost(hostname) {
      const site = SITES.find((s) => s.host.test(hostname));
      return site ? { name: site.name, selector: site.cards.join(',') } : null;
    },
  };
})();

// Decides whether a piece of text is a spoiler. No DOM in here, so it runs in
// Node for the unit tests (test/unit/matcher.test.js).
(() => {
  'use strict';
  const SS = (globalThis.SpoilerShield ??= {});

  const MAX_LENGTH = 20000;

  /** Lower-case, strip accents and apostrophes, turn URL and hashtag punctuation into spaces. */
  function normalize(text) {
    return text
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[̀-ͯ'’`]/g, '')
      .replace(/[_\-+./#:|]+/g, ' ');
  }

  const escapeRegExp = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  /** The user's extra words: plain text, one per line or comma separated. */
  function extraPatterns(extra) {
    return String(extra || '')
      .split(/[\n,]/)
      .map((word) => normalize(word).trim())
      .filter((word) => word.length > 1)
      .map((word) => escapeRegExp(word).replace(/\s+/g, '\\s+'));
  }

  /**
   * @param {{strong: string[], weak?: string[], weakThreshold?: number, extra?: string}} options
   * @returns {{isSpoiler: (text: string) => boolean}}
   */
  function createMatcher({ strong, weak = [], weakThreshold = 2, extra = '' }) {
    // A pattern must start at a word boundary and must not run into another
    // letter: "gta" matches "gta6" and "#gta" but not "megtastic" or "gtag".
    const strongRe = new RegExp(
      '(?<![a-z0-9])(?:' +
        strong
          .concat(extraPatterns(extra))
          .map((p) => p + '(?![a-z])')
          .join('|') +
        ')'
    );
    const weakRes = weak.map((p) => new RegExp('(?<![a-z0-9])(?:' + p + ')(?![a-z0-9])'));

    function isSpoiler(text) {
      if (!text || text.length < 3) return false;
      const t = normalize(text.length > MAX_LENGTH ? text.slice(0, MAX_LENGTH) : text);
      if (strongRe.test(t)) return true;
      let hits = 0;
      for (const re of weakRes) if (re.test(t) && ++hits >= weakThreshold) return true;
      return false;
    }

    return { isSpoiler };
  }

  SS.normalize = normalize;
  SS.createMatcher = createMatcher;
})();

// Settings, stored wherever the script happens to be running:
//   - as a browser extension: extension storage
//   - as a userscript: the userscript manager's storage (GM_getValue / GM_setValue)
//   - loaded with a plain <script> tag (tests, demo): defaults only
(() => {
  'use strict';
  const SS = (globalThis.SpoilerShield ??= {});

  const DEFAULTS = Object.freeze({
    enabled: true, // master switch
    hard: false, // hard mode: no click-to-show
    extra: '', // the user's own words, one per line or comma separated
    off: [], // hostnames where the shield is paused
  });

  const ext = globalThis.browser ?? globalThis.chrome;
  const extStore = ext?.storage?.local;
  const hasGM = typeof GM_getValue === 'function' && typeof GM_setValue === 'function';
  const GM_KEY = 'settings';

  async function load() {
    try {
      if (extStore) return { ...DEFAULTS, ...(await extStore.get({ ...DEFAULTS })) };
      if (hasGM) return { ...DEFAULTS, ...JSON.parse(GM_getValue(GM_KEY, '{}')) };
    } catch {
      // Unreadable settings must never leave spoilers visible: fall back to defaults.
    }
    return { ...DEFAULTS };
  }

  async function save(patch) {
    if (extStore) return extStore.set(patch);
    if (hasGM) GM_setValue(GM_KEY, JSON.stringify({ ...(await load()), ...patch }));
  }

  /** Calls back with the full settings whenever they change, also from another tab. */
  function onChange(callback) {
    if (extStore) {
      ext.storage.onChanged.addListener((_changes, area) => {
        if (area === 'local') load().then(callback);
      });
    } else if (hasGM && typeof GM_addValueChangeListener === 'function') {
      GM_addValueChangeListener(GM_KEY, () => load().then(callback));
    }
  }

  SS.settings = { DEFAULTS, load, save, onChange };
})();

// The full-page cover. When the address or the title of a page is itself a
// spoiler (a GTA 6 video, a GTA subreddit, a search for it), hiding single
// posts is pointless, so the whole page goes behind one opaque layer.
(() => {
  'use strict';
  const SS = (globalThis.SpoilerShield ??= {});

  const COVER_ID = 'gta6-shield-cover';

  /**
   * @param {{isSpoiler: (text: string) => boolean, isHard: () => boolean, label: string}} options
   */
  function createPageCover({ isSpoiler, isHard, label }) {
    const dismissed = new Set();

    const pageKey = () => location.pathname + location.search;

    function wasDismissed() {
      if (dismissed.has(pageKey())) return true;
      try {
        return sessionStorage.getItem('gss-ok:' + pageKey()) === '1';
      } catch {
        return false;
      }
    }

    function pageIsSpoiler() {
      let url = location.href.split('#')[0];
      try {
        url = decodeURIComponent(url);
      } catch {}
      return isSpoiler(url + ' ' + document.title);
    }

    function button(text, primary, onClick) {
      const b = document.createElement('button');
      b.textContent = text;
      b.style.cssText =
        'font:600 14px system-ui,sans-serif;padding:10px 18px;border-radius:8px;cursor:pointer;border:1px solid #3a3d45;' +
        (primary ? 'background:#e8e9ec;color:#0e0f11;' : 'background:transparent;color:#a9adb6;');
      b.addEventListener('click', onClick);
      return b;
    }

    // Built with createElement, not innerHTML: YouTube enforces Trusted Types.
    function show() {
      if (document.getElementById(COVER_ID) || !document.documentElement) return;
      const cover = document.createElement('div');
      cover.id = COVER_ID;
      cover.style.cssText =
        'position:fixed;inset:0;z-index:2147483647;background:#0e0f11;color:#e8e9ec;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font:16px system-ui,sans-serif;text-align:center;padding:24px;';

      const heading = document.createElement('div');
      heading.textContent = `This page looks like ${label}`;
      heading.style.cssText = 'font:700 24px system-ui,sans-serif;';

      const note = document.createElement('div');
      note.textContent = 'Covered before you could read anything.';
      note.style.cssText = 'color:#8b8f98;max-width:420px;';

      const buttons = document.createElement('div');
      buttons.style.cssText = 'display:flex;gap:10px;margin-top:8px;';
      if (window.top === window) buttons.append(button('Go back', true, () => history.back()));
      if (!isHard()) {
        buttons.append(
          button('Show anyway', false, () => {
            dismissed.add(pageKey());
            try {
              sessionStorage.setItem('gss-ok:' + pageKey(), '1');
            } catch {}
            cover.remove();
          })
        );
      }

      cover.append(heading, note, buttons);
      document.documentElement.append(cover);
    }

    function remove() {
      document.getElementById(COVER_ID)?.remove();
    }

    /** Called on a timer: single-page apps change address and title without reloading. */
    function check() {
      if (!wasDismissed() && pageIsSpoiler()) {
        show();
        // The cover hides the picture, not the sound.
        for (const media of document.querySelectorAll('video, audio')) {
          try {
            if (!media.paused) media.pause();
          } catch {}
        }
      } else {
        remove();
      }
    }

    return { check, remove };
  }

  SS.COVER_ID = COVER_ID;
  SS.createPageCover = createPageCover;
})();

// The engine: watches the page, finds spoiler text, hides what contains it.
// Loaded last. docs/ARCHITECTURE.md explains the flow.
(() => {
  'use strict';
  const SS = globalThis.SpoilerShield;
  if (!SS || SS.shield) return; // already running in this frame

  // Tests and the demo page pretend to be another site with this.
  const host = globalThis.__spoilerShieldTestHost || location.hostname;
  const site = SS.sites.forHost(host);
  const label = SS.keywords.label;

  // Attributes that carry text a person can see or that name where a link goes.
  const TEXT_ATTRS = ['alt', 'title', 'aria-label', 'href', 'post-title', 'subreddit-prefixed-name', 'permalink', 'content-href'];
  const WATCHED_ATTRS = ['alt', 'title', 'aria-label', 'href', 'post-title'];
  const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEXTAREA', 'INPUT', 'SELECT', 'TITLE', 'HEAD', 'META', 'LINK']);
  const INLINE_TAGS = new Set(['A', 'SPAN', 'B', 'I', 'EM', 'STRONG', 'MARK', 'FONT', 'SMALL', 'CODE', 'U', 'IMG', 'PICTURE', 'SVG', 'YT-FORMATTED-STRING']);
  const PAGE_TAGS = new Set(['BODY', 'HTML', 'MAIN']); // never hide these
  const NATURAL_BLOCKS = 'article, li, tr, figure, blockquote, dd, [role="article"], [role="listitem"]';
  const STYLE_ID = 'gta6-shield-style';

  // data-gss="hide"  a site card, collapsed into a bar
  // data-gss="blur"  a block on any other site, blurred in place
  // data-gss="shown" revealed by a click
  const MARK = 'data-gss';
  const CSS = `
[${MARK}="hide"]{display:block!important;position:relative!important;overflow:hidden!important;box-sizing:border-box!important;padding:0!important;height:40px!important;min-height:40px!important;max-height:40px!important;visibility:hidden!important}
[${MARK}="hide"] *{visibility:hidden!important}
[${MARK}="hide"]::before{content:"${label} hidden · click to show";visibility:visible!important;position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font:600 12px/1 system-ui,sans-serif;letter-spacing:.02em;color:#8b8f98;background:#16171a;border:1px dashed #33363d;border-radius:8px;cursor:pointer;z-index:2147483646;box-sizing:border-box}
[${MARK}="blur"]{filter:blur(10px)!important;cursor:pointer!important;user-select:none!important}
[${MARK}="blur"] *{pointer-events:none!important}
html[data-gss-hard] [${MARK}="hide"]::before{content:"${label} hidden";cursor:default}
html[data-gss-hard] [${MARK}="blur"]{cursor:default!important}
`;

  let settings = { ...SS.settings.DEFAULTS };
  let matcher = null;
  let observer = null;
  let coverTimer = null;
  let running = false;

  const cardQueue = new Set(); // site cards waiting to be judged
  const signatures = new WeakMap(); // element -> text it was judged on
  const blurred = new WeakSet(); // elements marked by the generic path

  const cover = SS.createPageCover({
    isSpoiler: (text) => matcher.isSpoiler(text),
    isHard: () => settings.hard,
    label,
  });

  // ---------- reading text ----------

  function attributeText(el) {
    let out = '';
    for (const name of TEXT_ATTRS) {
      let value = el.getAttribute(name);
      if (!value) continue;
      if (name === 'href') {
        value = value.split(/[?#]/)[0]; // query strings are full of random ids
        try {
          value = decodeURIComponent(value);
        } catch {}
      }
      out += ' ' + value;
    }
    return out;
  }

  // Everything a card says: its text, its image descriptions, where its links
  // go. Cards nested inside it are left out, so a reply about GTA hides the
  // reply and not the comment it answers.
  function textOf(root, nestedSelector) {
    let out = attributeText(root);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (node.nodeType !== Node.ELEMENT_NODE) return NodeFilter.FILTER_ACCEPT;
        if (SKIP_TAGS.has(node.tagName)) return NodeFilter.FILTER_REJECT;
        if (nestedSelector && node.matches(nestedSelector)) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      },
    });
    let node;
    while ((node = walker.nextNode()) && out.length < 20000) {
      out += node.nodeType === Node.TEXT_NODE ? ' ' + node.nodeValue : attributeText(node);
    }
    return out;
  }

  // ---------- hiding ----------

  // Decide for one element, and undo an earlier decision if its text changed.
  // Sites like YouTube reuse the same element for a different video.
  function judge(el, mode, nestedSelector) {
    const text = textOf(el, nestedSelector);
    const current = el.getAttribute(MARK);

    if (!matcher.isSpoiler(text)) {
      if (current) {
        el.removeAttribute(MARK);
        signatures.delete(el);
        blurred.delete(el);
      }
      return;
    }

    const signature = text.length + ':' + text.slice(0, 200);
    if (current && signatures.get(el) === signature) return; // same text: keep it hidden, or revealed
    signatures.set(el, signature);
    el.setAttribute(MARK, mode);
    for (const video of el.querySelectorAll('video')) {
      try {
        video.pause();
      } catch {}
    }
  }

  // No adapter for this site, so guess how much to blur: start at the element
  // holding the text and grow to the smallest block that looks like one item.
  function pickBlock(el) {
    while (
      INLINE_TAGS.has(el.tagName.toUpperCase()) &&
      el.parentElement &&
      !PAGE_TAGS.has(el.parentElement.tagName) &&
      el.parentElement.textContent.length <= 3000
    ) {
      el = el.parentElement;
    }
    const natural = el.closest(NATURAL_BLOCKS);
    if (natural && natural.textContent.length <= 1500) return natural;
    // Climb while the parent is still small: this pulls in a card's thumbnail.
    while (el.parentElement && !PAGE_TAGS.has(el.parentElement.tagName) && el.parentElement.textContent.length <= 400) {
      el = el.parentElement;
    }
    return PAGE_TAGS.has(el.tagName) ? null : el;
  }

  function blurAround(el) {
    const block = pickBlock(el);
    if (!block) return;
    blurred.add(block);
    judge(block, 'blur', null);
  }

  function checkTextNode(node) {
    const text = node.nodeValue;
    if (text.length < 3 || !matcher.isSpoiler(text)) return;
    const parent = node.parentElement;
    if (parent && !parent.closest(`[${MARK}]`)) blurAround(parent);
  }

  function checkAttributes(el) {
    const text = attributeText(el);
    if (text.length > 4 && matcher.isSpoiler(text) && !el.closest(`[${MARK}]`)) blurAround(el);
  }

  function scanGeneric(root) {
    if (root.nodeType === Node.TEXT_NODE) return checkTextNode(root);
    if (SKIP_TAGS.has(root.tagName)) return;
    checkAttributes(root);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (node.nodeType !== Node.ELEMENT_NODE) return NodeFilter.FILTER_ACCEPT;
        if (SKIP_TAGS.has(node.tagName) || node.id === SS.COVER_ID || node.isContentEditable || node.hasAttribute(MARK)) {
          return NodeFilter.FILTER_REJECT;
        }
        if (site && node.matches(site.selector)) return NodeFilter.FILTER_REJECT; // cards have their own path
        return NodeFilter.FILTER_ACCEPT;
      },
    });
    let node;
    while ((node = walker.nextNode())) {
      if (node.nodeType === Node.TEXT_NODE) checkTextNode(node);
      else checkAttributes(node);
    }
  }

  // ---------- watching the page ----------

  // Entry point for anything new or changed: an element, or a text node.
  function scan(node) {
    const el = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
    if (!el || !el.isConnected || el.isContentEditable || el.closest('#' + SS.COVER_ID)) return;
    if (SKIP_TAGS.has(el.tagName)) return; // text inside <script>, <style>, <textarea>...

    if (site) {
      if (node.nodeType === Node.ELEMENT_NODE) for (const card of el.querySelectorAll(site.selector)) cardQueue.add(card);
      const card = el.closest(site.selector);
      if (card) {
        cardQueue.add(card);
        return;
      }
    }

    const marked = el.closest(`[${MARK}]`);
    if (marked) {
      if (blurred.has(marked)) judge(marked, 'blur', null); // its text changed: look again
      return;
    }
    scanGeneric(node);
  }

  function judgeQueuedCards() {
    for (const card of cardQueue) if (card.isConnected) judge(card, 'hide', site.selector);
    cardQueue.clear();
  }

  // Runs synchronously inside the MutationObserver callback, which the browser
  // calls before it paints. That is why hidden posts never flash on screen.
  function onMutations(records) {
    for (const record of records) {
      if (record.type === 'childList') {
        for (const node of record.addedNodes) {
          if (node.nodeType === Node.ELEMENT_NODE || node.nodeType === Node.TEXT_NODE) scan(node);
        }
      } else {
        scan(record.target);
      }
    }
    if (cardQueue.size) judgeQueuedCards();
  }

  function onClick(event) {
    const el = event.target instanceof Element ? event.target.closest(`[${MARK}="hide"],[${MARK}="blur"]`) : null;
    if (!el) return;
    // The click must not open the hidden link, in either mode.
    event.preventDefault();
    event.stopImmediatePropagation();
    if (!settings.hard) el.setAttribute(MARK, 'shown');
  }

  // ---------- on / off ----------

  function start() {
    const root = document.documentElement;
    if (!root) {
      // Userscript managers can run before <html> exists.
      new MutationObserver((_records, self) => {
        if (!document.documentElement) return;
        self.disconnect();
        apply();
      }).observe(document, { childList: true });
      return;
    }
    running = true;

    const style = document.createElement('style');
    style.id = STYLE_ID;
    style.textContent = CSS;
    (document.head || root).append(style);
    root.toggleAttribute('data-gss-hard', !!settings.hard);

    observer = new MutationObserver(onMutations);
    observer.observe(document, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: true,
      attributeFilter: WATCHED_ATTRS,
    });
    document.addEventListener('click', onClick, true);

    scan(root);
    if (cardQueue.size) judgeQueuedCards();
    cover.check();
    coverTimer = setInterval(cover.check, 700);
  }

  function stop() {
    if (!running) return;
    running = false;
    observer.disconnect();
    clearInterval(coverTimer);
    document.removeEventListener('click', onClick, true);
    cardQueue.clear();
    for (const el of document.querySelectorAll(`[${MARK}]`)) el.removeAttribute(MARK);
    document.getElementById(STYLE_ID)?.remove();
    document.documentElement?.removeAttribute('data-gss-hard');
    cover.remove();
  }

  /** (Re)start with the given settings. Old marks are dropped so new words and modes take effect. */
  function apply(next) {
    if (next) settings = next;
    matcher = SS.createMatcher({ ...SS.keywords, extra: settings.extra });
    stop();
    if (settings.enabled && !settings.off.includes(host)) start();
  }

  function applyIfChanged(next) {
    if (JSON.stringify(next) !== JSON.stringify(settings)) apply(next);
  }

  SS.shield = {
    host,
    apply,
    get settings() {
      return settings;
    },
  };

  // Start on defaults straight away so nothing shows while settings load.
  apply();
  SS.settings.load().then(applyIfChanged);
  SS.settings.onChange(applyIfChanged);
})();

// Userscript only: a userscript has no popup, so the same four settings go in
// the userscript manager's menu (click the Violentmonkey / Tampermonkey icon).
(() => {
  'use strict';
  const SS = globalThis.SpoilerShield;
  if (typeof GM_registerMenuCommand !== 'function' || !SS?.shield || window.top !== window) return;

  const { shield, settings: store } = SS;

  function toast(message) {
    const el = document.createElement('div');
    el.textContent = 'Spoiler Shield: ' + message;
    el.style.cssText =
      'position:fixed;right:16px;bottom:16px;z-index:2147483647;background:#16171a;color:#e8e9ec;border:1px solid #33363d;border-radius:8px;padding:10px 14px;font:600 13px system-ui,sans-serif;';
    document.documentElement.append(el);
    setTimeout(() => el.remove(), 2200);
  }

  async function change(patch, message) {
    await store.save(patch);
    shield.apply({ ...shield.settings, ...patch });
    toast(message);
  }

  GM_registerMenuCommand('Shield on / off', () => {
    const enabled = !shield.settings.enabled;
    change({ enabled }, enabled ? 'on' : 'off everywhere');
  });

  GM_registerMenuCommand('Pause / resume on this site', () => {
    const paused = shield.settings.off.includes(shield.host);
    const off = shield.settings.off.filter((h) => h !== shield.host);
    if (!paused) off.push(shield.host);
    change({ off }, paused ? 'back on for ' + shield.host : 'paused on ' + shield.host);
  });

  GM_registerMenuCommand('Hard mode on / off', () => {
    const hard = !shield.settings.hard;
    change({ hard }, hard ? 'hard mode on, no click-to-show' : 'hard mode off');
  });

  GM_registerMenuCommand('Extra words to hide…', () => {
    const current = shield.settings.extra.replace(/\n+/g, ', ');
    const answer = prompt('Extra words to hide, separated by commas:', current);
    if (answer !== null) change({ extra: answer }, 'words saved');
  });
})();
